// Package wasm holds PCRE2 compiled to WebAssembly and translated to Go by
// wasm2go. pcre2.wasm.go and versions.go are generated by
// buildtools/wasm/Containerfile; run `make generate` to rebuild them.
//
// The module imports only gopcre2.callout (buildtools/wasm/imports.txt),
// which New takes as its Xgopcre2 argument. It exports its linear memory and
// the functions listed in buildtools/wasm/exports.txt.
package wasm
